function drawGame() {
  if (!game || !canvas || !ctx) return;

  const width = game.width;
  const height = game.height;

  // 清除画布
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // 计算视野中心
  const center_x = game.player.x;
  const center_y = game.player.y;

  // 绘制地图
